orders = await orders_get_orders()
# inspect structure
if isinstance(orders, dict):
    keys = list(orders.keys())
    sample = orders[keys[0]][:2] if isinstance(orders[keys[0]], list) else orders
    return {"type": "dict", "keys": keys, "sample": sample}
else:
    return {"type": type(orders).__name__, "len": len(orders), "sample": orders[:2]}

orders = await orders_get_orders()
totals = {}
for o in orders:
    r = o["region"]
    totals[r] = totals.get(r, 0) + o["amount"]
totals = {k: round(v, 2) for k, v in sorted(totals.items())}
return {"totals": totals, "count": len(orders)}
